func djb33(seed uint32, k string) uint32 {
	h := seed
	for i := 0; i < len(k); i++ {
		h = h*33 + uint32(k[i])
	}
	h ^= h >> 16
	h *= 0x7feb352d
	h ^= h >> 15
	h *= 0x846ca68b
	h ^= h >> 16
	return h
}

